import { after } from 'next/server';

async function logPageView() {
  // Simulate logging to an external analytics service
  console.log('Logging page view...');
  await new Promise(resolve => setTimeout(resolve, 2000));
  console.log('Page view logged successfully!');
}

export default function Welcome() {
  // Schedule the logging task to run after the response is sent
  after(async () => {
    await logPageView();
  });

  return (
    <div className="p-8 font-sans">
      <h1 className="text-3xl font-bold mb-4">Welcome to our site!</h1>
      <p className="text-gray-600">
        We're glad you're here. Your visit is being anonymously logged for analytics.
      </p>
    </div>
  );
}

